package com.bank.exec.service;

import java.util.concurrent.*;
import java.util.logging.Logger;

// Returns the right executor shape for a named banking workload.
public class ExecutorChooser {
    private static final Logger log = Logger.getLogger(ExecutorChooser.class.getName());

    public enum Workload { STEADY_SETTLEMENT, SMS_BURST, NIGHTLY_INTEREST, LEDGER_SUM }

    public ExecutorService choose(Workload workload) {
        switch (workload) {
            case STEADY_SETTLEMENT:
                log.info("STEADY_SETTLEMENT → FixedThreadPool(16) (predictable load)");
                return Executors.newFixedThreadPool(16);
            case SMS_BURST:
                log.info("SMS_BURST → CachedThreadPool (short bursty tasks)");
                return Executors.newCachedThreadPool();
            case NIGHTLY_INTEREST:
                log.info("NIGHTLY_INTEREST → ScheduledThreadPool(2) (timed job)");
                return Executors.newScheduledThreadPool(2);
            case LEDGER_SUM:
                log.info("LEDGER_SUM → ForkJoinPool (CPU recursion, work stealing)");
                return new ForkJoinPool();
            default:
                throw new IllegalArgumentException("unknown workload: " + workload);
        }
    }
}
