package com.bank.exec.service;

import java.util.concurrent.RecursiveTask;

// Divide-and-conquer sum of transaction amounts (in paise) → ideal fork/join work.
public class TransactionSumTask extends RecursiveTask<Long> {
    private static final int THRESHOLD = 1000;
    private final long[] amounts;
    private final int lo;
    private final int hi;

    public TransactionSumTask(long[] amounts, int lo, int hi) {
        this.amounts = amounts;
        this.lo = lo;
        this.hi = hi;
    }

    @Override
    protected Long compute() {
        if (hi - lo <= THRESHOLD) {              // small chunk: sum directly, no IO
            long sum = 0;
            for (int i = lo; i < hi; i++) sum += amounts[i];
            return sum;
        }
        int mid = (lo + hi) >>> 1;
        TransactionSumTask left = new TransactionSumTask(amounts, lo, mid);
        left.fork();                              // push left onto this thread's deque
        TransactionSumTask right = new TransactionSumTask(amounts, mid, hi);
        long rightResult = right.compute();       // compute right in this thread
        long leftResult = left.join();            // join left (maybe stolen by another)
        return leftResult + rightResult;
    }
}
```

