// ─── File: src/main/java/com/bank/exec/service/ExecutorSelectionApplication.java ───
package com.bank.exec.service;

import java.util.concurrent.*;
import java.util.logging.Logger;

// Runnable demo exercising all four executor shapes.
public class ExecutorSelectionApplication {
    private static final Logger log = Logger.getLogger(ExecutorSelectionApplication.class.getName());

    public static void main(String[] args) throws Exception {
        ExecutorChooser chooser = new ExecutorChooser();

        // 1. Steady settlement
        ExecutorService settlement = chooser.choose(ExecutorChooser.Workload.STEADY_SETTLEMENT);
        settlement.submit(() -> log.info("Settling trade for SAV2001"));
        settlement.shutdown();

        // 2. SMS burst
        ExecutorService sms = chooser.choose(ExecutorChooser.Workload.SMS_BURST);
        for (int i = 0; i < 5; i++) {
            final int n = i;
            sms.submit(() -> log.info("SMS alert #" + n + " to CUR3001"));
        }
        sms.shutdown();

        // 3. Nightly interest (fire once immediately for the demo)
        ScheduledExecutorService interest =
                (ScheduledExecutorService) chooser.choose(ExecutorChooser.Workload.NIGHTLY_INTEREST);
        interest.schedule(() -> log.info("Posting interest to SAV2001"), 0, TimeUnit.SECONDS);
        interest.shutdown();

        // 4. Ledger sum via fork/join
        long[] amounts = new long[1_000_000];
        for (int i = 0; i < amounts.length; i++) amounts[i] = 100;   // Rs.1.00 each
        ForkJoinPool fjp = (ForkJoinPool) chooser.choose(ExecutorChooser.Workload.LEDGER_SUM);
        long total = fjp.invoke(new TransactionSumTask(amounts, 0, amounts.length));
        log.info("Ledger total (paise): " + total);
        fjp.shutdown();
    }
}
