package com.bank.exec.service;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.assertThat;

class ExecutorChooserTest {

    private final ExecutorChooser chooser = new ExecutorChooser();

    @Test
    void steadyWorkload_returnsFixedPool() {
        ExecutorService es = chooser.choose(ExecutorChooser.Workload.STEADY_SETTLEMENT);
        assertThat(es).isInstanceOf(ThreadPoolExecutor.class);
        assertThat(((ThreadPoolExecutor) es).getCorePoolSize()).isEqualTo(16);
        es.shutdown();
    }

    @Test
    void burstWorkload_returnsCachedPool() {
        ExecutorService es = chooser.choose(ExecutorChooser.Workload.SMS_BURST);
        ThreadPoolExecutor tpe = (ThreadPoolExecutor) es;
        assertThat(tpe.getCorePoolSize()).isEqualTo(0);                 // cached: 0 core
        assertThat(tpe.getMaximumPoolSize()).isEqualTo(Integer.MAX_VALUE);
        es.shutdown();
    }

    @Test
    void nightlyWorkload_returnsScheduledPool() {
        ExecutorService es = chooser.choose(ExecutorChooser.Workload.NIGHTLY_INTEREST);
        assertThat(es).isInstanceOf(ScheduledExecutorService.class);
        es.shutdown();
    }

    @Test
    void ledgerWorkload_returnsForkJoinPool() {
        ExecutorService es = chooser.choose(ExecutorChooser.Workload.LEDGER_SUM);
        assertThat(es).isInstanceOf(ForkJoinPool.class);
        es.shutdown();
    }

    @Test
    void forkJoinSum_matchesSequentialSum() {
        long[] amounts = new long[100_000];
        long expected = 0;
        for (int i = 0; i < amounts.length; i++) { amounts[i] = i; expected += i; }
        ForkJoinPool fjp = (ForkJoinPool) chooser.choose(ExecutorChooser.Workload.LEDGER_SUM);
        long result = fjp.invoke(new TransactionSumTask(amounts, 0, amounts.length));
        assertThat(result).isEqualTo(expected);
        fjp.shutdown();
    }
}
